import type { GeneratedAlways } from "kysely";

export type Visibility = "public" | "internal";
export type DocumentStatus = "active" | "quarantined";

export type DocumentRow = {
  id: string;
  tenantId: string;
  visibility: Visibility;
  title: string;
  sourceUri: string;
  contentHash: string;
  version: number;
  status: DocumentStatus;
  findings: unknown;
  createdAt: Date;
  updatedAt: Date;
};

export type ChunkRow = {
  id: string;
  documentId: string;
  tenantId: string;
  visibility: Visibility;
  ordinal: number;
  heading: string;
  body: string;
  /** Generated by Postgres. Never written. */
  tsv: GeneratedAlways<string>;
  /** A pgvector literal such as `[0.1,0.2]`. Null when no embedding model is configured. */
  embedding: string | null;
  embeddingModel: string | null;
};

export type DocumentsDatabase = {
  documents: DocumentRow;
  chunks: ChunkRow;
};
